//! 🧪️ Actual native preview turns retain the original receipts, payload loans and physical owners.
use super::*;
#[derive(Clone,Copy)]
enum Event{Yield,Preview,Checkpoint,Complete,Cancelled,Fault}
struct OriginalPreviewJob{events:&'static[Event],cursor:usize,publication:RetainedJobPublication,delivered:bool,closing:bool}
const FAULT:&[u8]=b"original exact producer fault bytes";
impl OriginalPreviewJob{
 fn demand(&self)->Result<RetirementDemand,ValueError>{if self.publication.terminal_is_empty(){Ok(RetirementDemand{depth:1,..Default::default()})}else{self.publication.retirement_demands()}}
}
impl InteractiveJob for OriginalPreviewJob{
 fn step<'a>(&'a mut self,cx:&mut StepContext<'_>)->Result<Option<JobOutcomeBorrow<'a>>,ValueError>{
  if self.delivered{let step=self.publication.close_step(cx.retained_grant())?;cx.consume_retained(step.progress())?;if matches!(step,RetainedCloneStep::Complete(_)){self.delivered=false;self.cursor+=1;}return Ok(None)}
  let event=self.events.get(self.cursor).copied().unwrap_or(Event::Yield);
  match event{
   Event::Yield=>{let result=JobOutcomeBorrow::admit_yield(cx)?;if result.is_some(){self.cursor+=1;}Ok(result)},
   Event::Complete=>JobOutcomeBorrow::admit_complete(cx,None,None),
   Event::Cancelled=>JobOutcomeBorrow::admit_cancelled(cx),
   event=>{let kind=match event{Event::Preview=>JobPublicationKind::Preview,Event::Checkpoint=>JobPublicationKind::Checkpoint{applied_progress:7},Event::Fault=>JobPublicationKind::Fault,_=>unreachable!()};let result=self.publication.advance_from_source(kind,FAULT,cx)?;if result.is_some(){self.delivered=true;}Ok(result)}
  }
 }
 fn borrow_outcome<'a>(&'a self,descriptor:&'a JobOutcomeDescriptor)->Result<JobOutcomeView<'a>,ValueError>{match descriptor.kind(){JobOutcomeKind::Yield=>descriptor.yielded(),JobOutcomeKind::Cancelled=>descriptor.cancelled(),JobOutcomeKind::Complete=>descriptor.complete(None,None),_=>self.publication.borrow_outcome(descriptor)}}
 fn begin_close(&mut self){self.closing=true;}
 fn close_step(&mut self,grant:RetainedCloneGrant)->InteractiveJobCloseStep{
  let demand=match self.demand(){Ok(demand)=>demand,Err(error)=>return InteractiveJobCloseStep::Refused{kind:error.kind,progress:error.retained_progress()}};
  if grant.maximum_items==0||grant.maximum_copy_bytes<demand.copy_bytes||grant.maximum_capacity_bytes<demand.capacity_bytes||grant.maximum_release_bytes<demand.release_bytes||grant.maximum_depth<demand.depth{return InteractiveJobCloseStep::Pending{progress:Default::default()}}
  if !self.publication.terminal_is_empty(){return match self.publication.close_step(grant){Ok(step)=>InteractiveJobCloseStep::Pending{progress:step.progress()},Err(error)=>InteractiveJobCloseStep::Refused{kind:error.kind,progress:error.retained_progress()}}}
  if self.delivered{self.delivered=false;return InteractiveJobCloseStep::Pending{progress:RetainedCloneProgress{copied_items:1,..Default::default()}}}
  InteractiveJobCloseStep::Complete{progress:Default::default()}
 }
 fn terminal_is_empty(&self)->bool{self.closing&&!self.delivered&&self.publication.terminal_is_empty()}
 fn next_close_copy_byte_demand(&self)->Result<usize,ValueError>{Ok(self.demand()?.copy_bytes)}
 fn next_close_capacity_byte_demand(&self,_:usize)->Result<usize,ValueError>{Ok(self.demand()?.capacity_bytes)}
 fn next_close_release_byte_demand(&self)->Result<usize,ValueError>{Ok(self.demand()?.release_bytes)}
 fn next_close_depth_demand(&self)->Result<usize,ValueError>{Ok(self.demand()?.depth)}
}
fn observed<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
fn physical(progress:RetainedCloneProgress,heap:(usize,usize),grant:RetainedCloneGrant){assert!(progress.fits(grant));assert_eq!((progress.retained_capacity_bytes,progress.released_bytes),heap)}
fn policy(row:&serde_json::Value)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:row[0].as_u64().unwrap()as usize,maximum_copy_bytes:row[1].as_u64().unwrap()as usize,maximum_capacity_bytes:row[2].as_u64().unwrap()as usize,maximum_release_bytes:row[3].as_u64().unwrap()as usize,maximum_depth:row[4].as_u64().unwrap()as usize}}
fn original_clock()->Option<u64>{Some(1000)}
#[test]
fn original_preview_driver_preserves_native_receipts_fault_loan_and_paid_closure(){
 let _slots=worker_session_slots_shared();let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let admission=policy(&law["admissionGrant"]);let grant=policy(&law["stepGrant"]);let operation=OperationId(law["originalIdentity"][0].as_u64().unwrap());let generation=Generation(law["originalIdentity"][1].as_u64().unwrap());assert_eq!(law["faultSource"].as_str().unwrap().as_bytes(),FAULT);
 for (index,events)in[&[Event::Yield,Event::Complete][..],&[Event::Preview,Event::Checkpoint,Event::Complete][..],&[Event::Cancelled][..],&[Event::Fault][..],&[Event::Yield][..]].into_iter().enumerate(){
  let row=&law["cases"][index];let((cancel,birth),heap)=observed(||CancelToken::admit_root(admission).unwrap().unwrap());physical(birth,heap,admission);let mut born=heap.0;let mut released=heap.1;let((mut authority,birth),heap)=observed(||JobPayloadAuthority::admit(operation,generation,admission).unwrap().unwrap());physical(birth,heap,admission);born+=heap.0;released+=heap.1;let mut sequence=0;let mut receipt=Default::default();let mut cx=StepContext::with_payload_authority(operation,generation,StepBudget::new(1,u64::MAX,admission),&cancel,original_clock,&mut sequence,&mut receipt,&authority).unwrap();let(alias,heap)=observed(||cx.admit_original_cancel_alias().unwrap().unwrap());physical(cx.retained_progress(),heap,admission);drop(cx);
  let original_job=OriginalPreviewJob{events,cursor:0,publication:RetainedJobPublication::new(),delivered:false,closing:false};let params=BatchJobParams{operation,generation,cancel:alias,config:BatchDriveConfig{retained:admission,site:"original-preview-driver",stage:InteractiveStage::InteractiveStep,fuel_per_step:1,step_budget_us:100000},now_us:original_clock};let(mut session,heap)=observed(||admit_original_fixture_owner!(BatchJobSession,original_job,params).unwrap());born+=heap.0;released+=heap.1;assert_eq!(heap.1,0);assert_eq!(session.original_identity().unwrap(),Some((operation,generation)));let original_session=std::ptr::addr_of!(session);let limits=JobPreviewLimits{maximum_turns:row["maximumTurns"].as_u64().unwrap_or(law["maximumTurns"].as_u64().unwrap()),maximum_wall_us:law["maximumWallMicros"].as_u64().unwrap()};let mut driver=JobPreviewDriver::new(limits);let mut turns=0;let mut semantic_fault=0;let mut total_copy=0;
  let verdict=loop{
   for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let mut receipt=Default::default();let mut cx=StepContext::with_payload_authority(operation,generation,StepBudget::new(1,u64::MAX,denied),&cancel,original_clock,&mut sequence,&mut receipt,&authority).unwrap();let(result,heap)=observed(||driver.advance(&mut session,&mut cx).unwrap());assert!(matches!(result,JobPreviewStep::Pending));assert_eq!(heap,(0,0));assert_eq!(cx.retained_progress(),Default::default());}
   let mut receipt=Default::default();let mut cx=StepContext::with_payload_authority(operation,generation,StepBudget::new(1,u64::MAX,grant),&cancel,original_clock,&mut sequence,&mut receipt,&authority).unwrap();let phase=driver.phase;let(result,heap)=observed(||driver.advance(&mut session,&mut cx).unwrap());let progress=cx.retained_progress();physical(progress,heap,grant);born+=heap.0;released+=heap.1;total_copy+=progress.copied_bytes;if phase!=JobPreviewPhase::Run{assert_eq!(progress.copied_bytes,0)}drop(cx);
   let mut fault_input=false;match result{JobPreviewStep::Complete(verdict)=>break verdict,JobPreviewStep::Fault{detail}=>{semantic_fault+=1;assert_eq!(detail.len(),FAULT.len());let pointer=detail as*const _;let page=detail.page(0).unwrap().as_ptr();let mut offset=0;for index in 0..detail.page_count(){let bytes=detail.page(index).unwrap();assert_eq!(bytes,&FAULT[offset..offset+bytes.len()]);offset+=bytes.len();}assert_eq!(offset,FAULT.len());for _ in 0..3{let mut receipt=Default::default();let zero_copy=RetainedCloneGrant{maximum_copy_bytes:0,..grant};let mut cx=StepContext::with_payload_authority(operation,generation,StepBudget::new(1,u64::MAX,zero_copy),&cancel,original_clock,&mut sequence,&mut receipt,&authority).unwrap();let(result,heap)=observed(||driver.advance(&mut session,&mut cx).unwrap());assert_eq!(heap,(0,0));assert_eq!(cx.retained_progress(),Default::default());match result{JobPreviewStep::Fault{detail}=>{assert_eq!(detail as*const _,pointer);assert_eq!(detail.page(0).unwrap().as_ptr(),page)},_=>panic!("Fault input must remain borrowed before explicit acceptance")}}fault_input=true},JobPreviewStep::Pending=>{}}
   if fault_input{for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let mut receipt=Default::default();let mut cx=StepContext::with_payload_authority(operation,generation,StepBudget::new(1,u64::MAX,denied),&cancel,original_clock,&mut sequence,&mut receipt,&authority).unwrap();let(accepted,heap)=observed(||driver.accept_fault_input(&session,&mut cx).unwrap());assert!(!accepted);assert_eq!(heap,(0,0));assert_eq!(cx.retained_progress(),Default::default());}let mut receipt=Default::default();let zero_copy=RetainedCloneGrant{maximum_copy_bytes:0,..grant};let mut cx=StepContext::with_payload_authority(operation,generation,StepBudget::new(1,u64::MAX,zero_copy),&cancel,original_clock,&mut sequence,&mut receipt,&authority).unwrap();let(accepted,heap)=observed(||driver.accept_fault_input(&session,&mut cx).unwrap());assert!(accepted);physical(cx.retained_progress(),heap,zero_copy);assert_eq!(cx.retained_progress(),RetainedCloneProgress{copied_items:1,..Default::default()});}
   turns+=1;assert!(turns<10000);assert_eq!(std::ptr::addr_of!(session),original_session);
  };
  let expected=match row["verdict"].as_str().unwrap(){"complete"=>JobPreviewStatus::Complete,"cancelled"=>JobPreviewStatus::Cancelled,"fault"=>JobPreviewStatus::Fault,"budget"=>JobPreviewStatus::Budget,_=>unreachable!()};assert_eq!(verdict,JobPreviewVerdict{status:expected,outcomes:row["outcomes"].as_u64().unwrap()});assert_eq!(semantic_fault,usize::from(expected==JobPreviewStatus::Fault));assert!(session.terminal_is_empty()&&driver.terminal_is_empty());assert_eq!(session.original_identity().unwrap(),None);assert!(session.take_checked_out_retained_step_receipt().is_none());assert_eq!(observed(||drop(session)).1,(0,0));let(step,heap)=observed(||authority.close_step(admission).unwrap());physical(step.progress(),heap,admission);born+=heap.0;released+=heap.1;assert!(authority.terminal_is_empty());let mut root=semio_framework_async::CancelTokenRetirement::from_token(cancel);while !root.terminal_is_empty(){let(step,heap)=observed(||root.close_step(RetainedCloneGrant{maximum_copy_bytes:0,..admission}).unwrap());physical(step.progress(),heap,admission);born+=heap.0;released+=heap.1;}assert_eq!(born,released);assert_eq!(observed(||{drop(authority);drop(root);drop(driver)}).1,(0,0));eprintln!("[DEBUG] actual original preview case={index} turns={turns} status={expected:?} outcomes={} totalCopy={total_copy} exactBornRelease={born} sameSession={original_session:p} FaultAcceptBeforeACK metadata0 terminalDrop0",verdict.outcomes);
 }
}

